<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if(isset($_GET['open'])){$id=(int)$_GET['open'];$st=$pdo->prepare('SELECT action_url FROM admin_notifications WHERE id=?');$st->execute([$id]);$url=$st->fetchColumn();$pdo->prepare('UPDATE admin_notifications SET is_read=1 WHERE id=?')->execute([$id]);header('Location: '.($url?:'notifications.php'));exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='read_all')$pdo->exec('UPDATE admin_notifications SET is_read=1');elseif($a==='clear_read')$pdo->exec('DELETE FROM admin_notifications WHERE is_read=1');flash('success','Notification center updated.');header('Location: notifications.php');exit;}$notes=$pdo->query('SELECT * FROM admin_notifications ORDER BY id DESC LIMIT 100')->fetchAll();$activity=$pdo->query('SELECT l.*,u.username FROM activity_log l LEFT JOIN admin_users u ON u.id=l.admin_id ORDER BY l.id DESC LIMIT 100')->fetchAll();$pageTitle='Notifications & Activity';$active='notifications';require __DIR__.'/_header.php';?><div class="page-heading"><div><p class="eyebrow">ACTIVITY CENTER</p><h1>Notifications & change history</h1><p class="muted">See what needs attention and review recent administrator actions.</p></div><form method="post" class="heading-actions"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><button class="button secondary small" name="action" value="read_all">Mark all read</button><button class="button danger-lite small" name="action" value="clear_read">Clear read</button></form></div><div class="activity-layout"><section class="panel"><div class="section-heading"><div><p class="eyebrow">NOTIFICATIONS</p><h2>Attention center</h2></div></div><div class="notification-list"><?php if(!$notes):?><div class="empty-state"><strong>All clear</strong><p>System notifications will appear here.</p></div><?php endif;foreach($notes as $n):?><a class="notification-item <?=$n['is_read']?'read':''?>" href="notifications.php?open=<?=$n['id']?>"><span class="notification-dot <?=h($n['notification_type'])?>"></span><div><strong><?=h($n['title'])?></strong><p><?=h($n['message'])?></p><small><?=h($n['created_at'])?></small></div></a><?php endforeach;?></div></section><section class="panel"><div class="section-heading"><div><p class="eyebrow">ACTIVITY LOG</p><h2>Recent changes</h2></div></div><div class="timeline"><?php foreach($activity as $a):?><article><span></span><div><strong><?=h($a['description'])?></strong><small><?=h($a['username']?:'System')?> · <?=h($a['created_at'])?></small></div></article><?php endforeach;?></div></section></div><?php require __DIR__.'/_footer.php';